SELECT r.order_id,r.request_id,w.current_config,w.business_clock,CASE WHEN (SELECT COUNT(*) FROM current_routes c WHERE c.request_id=r.request_id AND c.route_id IS NOT NULL)=0 THEN 'missing-or-expired' WHEN (SELECT COUNT(*) FROM current_routes c WHERE c.request_id=r.request_id AND c.route_id IS NOT NULL)>1 THEN 'ambiguous' ELSE 'effective' END AS current_route,CASE WHEN EXISTS(SELECT 1 FROM current_routes c JOIN partners p ON p.partner_id=c.partner_id WHERE c.request_id=r.request_id AND p.enabled=0) THEN 'disabled' WHEN EXISTS(SELECT 1 FROM current_routes c JOIN partners p ON p.partner_id=c.partner_id WHERE c.request_id=r.request_id AND p.enabled=1) THEN 'enabled' ELSE 'unknown' END AS partner_state,CASE WHEN EXISTS(SELECT 1 FROM latest_attempts a JOIN assignments x ON x.attempt_id=a.attempt_id WHERE a.request_id=r.request_id AND a.state='accepted') THEN 'accepted' ELSE 'missing' END AS assignment_state FROM requests r CROSS JOIN workspace_state w WHERE r.order_id=@order_id
